import * as THREE from 'three';

const canvas=document.querySelector('#world');
const scene=new THREE.Scene();
scene.background=new THREE.Color(0x9bc8ca);
scene.fog=new THREE.FogExp2(0xa6c9c4,0.00225);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,700);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.18;
const hemi=new THREE.HemisphereLight(0xe4f6ed,0x59644b,2.1);scene.add(hemi);
const sun=new THREE.DirectionalLight(0xffedc4,3.2);sun.position.set(-80,110,45);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-115;sun.shadow.camera.right=115;sun.shadow.camera.top=115;sun.shadow.camera.bottom=-115;sun.shadow.bias=-.00015;scene.add(sun);
const fill=new THREE.DirectionalLight(0x9ac4ff,.48);fill.position.set(65,35,-90);scene.add(fill);
const mat=(color,roughness=.85,extra={})=>new THREE.MeshStandardMaterial({color,roughness,...extra});
const mats={grass:mat(0x718e59),darkgrass:mat(0x526d49),leaf:mat(0x496e52),leaf2:mat(0x66865a),bark:mat(0x665342),stone:mat(0x888a7c),lightstone:mat(0xb9ae8c),sand:mat(0xc8b785),water:mat(0x5ca7a5,.25,{transparent:true,opacity:.76,metalness:.1}),cloth:mat(0xc47f57),skin:mat(0xd2a77e),leather:mat(0x473d35),gold:mat(0xc8a956,.45,{metalness:.48}),enemy:mat(0x57494b),glow:mat(0xe5ca72,.28,{emissive:0xa87820,emissiveIntensity:1.1}),wood:mat(0x8e6945)};
const rnd=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function heightAt(x,z){const g=(cx,cz,sx,sz,h)=>h*Math.exp(-(((x-cx)/sx)**2+((z-cz)/sz)**2));let h=1.7*Math.sin(x*.027)*Math.cos(z*.024)+1.2*Math.sin(z*.052+x*.02);h+=g(-64,-84,34,32,28)+g(73,-94,32,39,34)+g(118,48,31,42,22)+g(-118,52,36,43,20)+g(6,-143,46,24,16);h+=g(45,28,21,24,6);h-=Math.max(0,5-Math.abs(x-12+Math.sin(z*.045)*9))*1.6;return h;}
function makeTerrain(){const N=170,size=360,positions=[],colors=[],indices=[];const c1=new THREE.Color(0x82985a),c2=new THREE.Color(0x50684a),c3=new THREE.Color(0x8a8770),c4=new THREE.Color(0xc2b17c),c5=new THREE.Color(0xd5d4c2);for(let j=0;j<=N;j++)for(let i=0;i<=N;i++){const x=(i/N-.5)*size,z=(j/N-.5)*size,y=heightAt(x,z);positions.push(x,y,z);let color=y<1.6?c4.clone().lerp(c1,clamp((y+.5)/2.5,0,1)):y>22?c3.clone().lerp(c5,clamp((y-22)/10,0,.8)):c1.clone().lerp(c2,clamp((y-8)/19,0,.4));const patch=.035*Math.sin(x*1.7+z*.91)*Math.sin(z*1.25-x*.42);color.offsetHSL(0,patch,patch*.5);colors.push(color.r,color.g,color.b);if(i<N&&j<N){const a=j*(N+1)+i,b=a+1,c=a+N+1,d=c+1;indices.push(a,c,b,b,c,d)}}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.setIndex(indices);geo.computeVertexNormals();const ground=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));ground.receiveShadow=true;scene.add(ground);}
makeTerrain();
// Hand-shaped river ribbon winding from high country down to the western sea.
function makeRiver(){const verts=[],idx=[],uv=[];const pts=[];for(let i=0;i<=160;i++){const t=i/160,z=150-t*315,x=13+Math.sin(t*7.7)*12+Math.sin(t*17)*4;pts.push(new THREE.Vector3(x,heightAt(x,z)+.2,z))}for(let i=0;i<pts.length;i++){const p=pts[i],before=pts[Math.max(0,i-1)],after=pts[Math.min(pts.length-1,i+1)],tangent=after.clone().sub(before).normalize(),side=new THREE.Vector3(-tangent.z,0,tangent.x).normalize();let w=2.2+Math.sin(i*.18)*.65;for(const sign of [-1,1]){verts.push(p.x+side.x*w,p.y,p.z+side.z*w);uv.push(sign>0?1:0,i/pts.length)}}for(let i=0;i<pts.length;i++)if(i<pts.length-1){const a=i*2,b=a+1,c=a+2,d=a+3;idx.push(a,b,c,b,d,c)}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));g.setIndex(idx);g.computeVertexNormals();const water=new THREE.Mesh(g,mats.water);water.receiveShadow=true;scene.add(water);}
makeRiver();
// distant atmospheric peaks and drifting clouds
for(let i=0;i<13;i++){const x=rnd(-190,190),z=rnd(-185,185);if(Math.abs(x)<130&&Math.abs(z)<130)continue;const peak=new THREE.Mesh(new THREE.ConeGeometry(rnd(12,26),rnd(32,66),6),mat(i%2?0x879a91:0x9eaaa0));peak.position.set(x,18,z);peak.castShadow=true;scene.add(peak)}
function addMesh(geo,material,x,y,z,scale=1,shadow=true){const o=new THREE.Mesh(geo,material);o.position.set(x,y,z);if(typeof scale==='number')o.scale.setScalar(scale);else o.scale.set(...scale);o.castShadow=shadow;o.receiveShadow=true;scene.add(o);return o}
function tree(x,z,s=1){const y=heightAt(x,z);const group=new THREE.Group();group.position.set(x,y,z);group.rotation.y=rnd(0,6.28);const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.28*s,.48*s,3.3*s,7),mats.bark);trunk.position.y=1.6*s;trunk.castShadow=true;group.add(trunk);for(let i=0;i<3;i++){const crown=new THREE.Mesh(new THREE.IcosahedronGeometry((2.3-i*.24)*s,1),i===1?mats.leaf2:mats.leaf);crown.position.set(rnd(-.3,.3)*s,(3.4+i*1.03)*s,rnd(-.3,.3)*s);crown.scale.set(1,.82,.92);crown.castShadow=true;group.add(crown)}scene.add(group);trees.push(group)}
const trees=[];for(let i=0;i<255;i++){let x=rnd(-155,155),z=rnd(-155,155);if(Math.abs(x)<23&&z>-40&&z<62)continue;if(Math.abs(x-(13+Math.sin((-z/315)*7.7)*12))<7)continue;if(heightAt(x,z)>20)continue;tree(x,z,rnd(.65,1.3))}
// Chalky boulders, flower patches, and fallen timber create readable trails.
for(let i=0;i<120;i++){let x=rnd(-160,160),z=rnd(-155,155);if(Math.abs(x)<17&&z>-35&&z<55)continue;const s=rnd(.35,1.4);let rock=addMesh(new THREE.DodecahedronGeometry(s,1),i%4?mats.stone:mats.lightstone,x,heightAt(x,z)+s*.45,z,[1.15,.82,.92]);rock.rotation.set(rnd(0,1),rnd(0,6),rnd(0,1))}
const flowers=[];const flowerMat=[mat(0xe5c77a),mat(0xd98b82),mat(0xc2c4dc)];for(let i=0;i<180;i++){let x=rnd(-150,150),z=rnd(-150,150);if(Math.abs(x)<14&&z>-30&&z<50)continue;let stem=new THREE.Group();stem.position.set(x,heightAt(x,z),z);const fl=addToGroup(new THREE.Mesh(new THREE.SphereGeometry(.12,6,5),flowerMat[i%3]),stem,0,rnd(.35,.65),0);fl.scale.set(1,.8,1);scene.add(stem);flowers.push(stem)}
function addToGroup(o,g,x,y,z){o.position.set(x,y,z);g.add(o);return o}

