function addToGroup(o,g,x,y,z){o.position.set(x,y,z);g.add(o);return o}

// The Windward Spire and the old road form a single visible destination from the starting meadow.
function ruinPillar(x,z,h=8,broken=false){const y=heightAt(x,z);const base=addMesh(new THREE.BoxGeometry(2.2,.65,2.2),mats.lightstone,x,y+.33,z);base.rotation.y=.12;const shaft=addMesh(new THREE.BoxGeometry(1.45,h,1.45),mats.stone,x,y+.65+h/2,z);shaft.rotation.y=.12;if(broken){shaft.rotation.z=.16;shaft.position.y-=1.4}const cap=addMesh(new THREE.BoxGeometry(1.95,.5,1.95),mats.lightstone,x,y+.65+h,z);cap.rotation.y=.12;return shaft}
function buildTower(x,z){const y=heightAt(x,z);const base=addMesh(new THREE.CylinderGeometry(3.2,4,1.4,8),mats.lightstone,x,y+.7,z);base.rotation.y=.2;const tower=addMesh(new THREE.CylinderGeometry(2.1,2.8,15,8),mats.stone,x,y+8.8,z);tower.rotation.y=.2;const roof=addMesh(new THREE.ConeGeometry(3.1,4,8),mats.darkgrass,x,y+18,z);roof.rotation.y=.2;for(let i=0;i<4;i++){const a=i*Math.PI/2+.2;const window=addMesh(new THREE.BoxGeometry(.52,2.6,.18),mat(0xe4c56f,.38,{emissive:0x9c6f25,emissiveIntensity:.8}),x+Math.cos(a)*2.12,y+9.3,z+Math.sin(a)*2.12);window.lookAt(x,y+9.3,z)}const ring=addMesh(new THREE.TorusGeometry(4.4,.15,8,36),mats.gold,x,y+17.3,z);ring.rotation.x=Math.PI/2;for(let i=0;i<8;i++){const p=addMesh(new THREE.OctahedronGeometry(.35),mats.glow,x+Math.cos(i*Math.PI/4)*4.4,y+17.3,z+Math.sin(i*Math.PI/4)*4.4);p.userData.float=i}landmarks.push({x,z,name:'THE WINDWARD SPIRE',radius:19,found:false});return tower}
const landmarks=[];
buildTower(30,-29);
for(let i=0;i<9;i++){const a=i/9*Math.PI*2;ruinPillar(30+Math.cos(a)*7,-29+Math.sin(a)*7,rnd(4,8),i%3===0)}
// A broken archway, low walls, and an old settlement on the east ridge.
for(let i=0;i<7;i++){const x=-23+i*7,z=12+Math.sin(i*.8)*2;ruinPillar(x,z,rnd(3,6),i%2===0)}
for(let i=0;i<5;i++){const wall=addMesh(new THREE.BoxGeometry(9,.85,.75),mats.stone,-44+i*4,heightAt(-44+i*4,28)+.45,28+i%2*4);wall.rotation.y=rnd(-.3,.3)}
function house(x,z,scale=1){const y=heightAt(x,z),g=new THREE.Group();g.position.set(x,y,z);const body=new THREE.Mesh(new THREE.BoxGeometry(7*scale,4*scale,6*scale),mats.lightstone);body.position.y=2*scale;body.castShadow=true;g.add(body);const roof=new THREE.Mesh(new THREE.ConeGeometry(5.5*scale,3.8*scale,4),mats.wood);roof.position.y=5.6*scale;roof.rotation.y=Math.PI/4;roof.castShadow=true;g.add(roof);const door=new THREE.Mesh(new THREE.BoxGeometry(1.15*scale,2.2*scale,.18),mats.bark);door.position.set(0,1.1*scale,3.05*scale);g.add(door);scene.add(g);return g}
house(-43,43,1);house(-56,48,.82);house(-34,55,.74);
// A warm camp and roadside merchant in the settlement.
const campfire=addMesh(new THREE.IcosahedronGeometry(.55,1),mat(0xf49b44,.45,{emissive:0xe75d1c,emissiveIntensity:2}),-43,heightAt(-43,37)+.75,37);const fireLight=new THREE.PointLight(0xff9a4e,9,23);fireLight.position.copy(campfire.position).y+=1;scene.add(fireLight);
function createCharacter(color=0x5b8064){const g=new THREE.Group();const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.53,.95,4,8),mat(color));torso.position.y=1.48;torso.castShadow=true;g.add(torso);const head=new THREE.Mesh(new THREE.SphereGeometry(.38,12,10),mats.skin);head.position.y=2.38;head.castShadow=true;g.add(head);const hood=new THREE.Mesh(new THREE.ConeGeometry(.46,.45,8),mat(0x536d61));hood.position.set(0,2.69,-.02);g.add(hood);for(let side of [-1,1]){const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.19,.62,3,6),mats.leather);leg.position.set(side*.24,.43,0);leg.castShadow=true;g.add(leg);const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.15,.55,3,6),mats.cloth);arm.position.set(side*.63,1.55,0);arm.rotation.z=side*-.13;g.add(arm)}const pack=new THREE.Mesh(new THREE.BoxGeometry(.6,.65,.3),mats.wood);pack.position.set(0,1.55,-.48);g.add(pack);return g}
const player={group:createCharacter(),x:0,z:13,y:0,vy:0,yaw:0,hp:5,maxHp:5,stamina:100,weapon:'sabre',durability:86,attack:0,dodge:0,gliding:false,grounded:true,swimming:false,invuln:0,damageFlash:0};player.y=heightAt(player.x,player.z);player.group.position.set(player.x,player.y,player.z);scene.add(player.group);
// Worn trail stones wind to the tower. A floating windstone marks the first interaction.
for(let i=0;i<24;i++){let t=i/23,x=-8+38*t,z=18-46*t+Math.sin(t*7)*4;let s=rnd(.3,.55);const tile=addMesh(new THREE.BoxGeometry(1.5,s,.9),i%4?mats.lightstone:mats.sand,x,heightAt(x,z)+s*.3,z);tile.rotation.y=rnd(-.3,.3)}
const windstone=addMesh(new THREE.OctahedronGeometry(1.05,0),mats.glow,4,heightAt(4,7)+1.4,7);windstone.rotation.set(.3,.2,.4);const windBase=addMesh(new THREE.CylinderGeometry(1.25,1.45,.65,7),mats.stone,4,heightAt(4,7)+.35,7);const windRing=addMesh(new THREE.TorusGeometry(1.65,.055,6,40),mats.gold,4,heightAt(4,7)+1.4,7);windRing.rotation.x=Math.PI/2;landmarks.push({x:4,z:7,name:'THE FIRST WINDSTONE',radius:8,found:false,kind:'stone'});

